import CoreGraphics
import Foundation
@testable import LeporeloCore

/// In-memory `PhotoSource` for pipeline and app-model tests. No disk, no network.
///
/// - `photos(matching:)` returns `photos` (the query is recorded, not interpreted).
/// - `thumbnail` serves `images[id]` or a generated checkerboard (never upscaled beyond `maxPixel`).
/// - `original` serves `originals[id]` or generated bytes with extension "jpg".
/// - Errors: `thumbnailErrors` / `originalErrors` per identifier (thrown on every call),
///   `cloudFailures[id] = n` makes `original` throw `.cloudUnavailable(id)` n times, then succeed.
///   `photosError` makes `photos(matching:)` throw.
/// - Holding: while `holdThumbnails` / `holdOriginals` is on, calls suspend until `releaseAll()`
///   (or until their task is cancelled, which throws `CancellationError`).
/// - Observation: per-identifier call counts, the peak number of concurrent calls, and an
///   `events` stream that yields when a call starts (single consumer).
final class FakePhotoSource: PhotoSource, @unchecked Sendable {
    enum Event: Sendable, Equatable {
        case thumbnailStarted(String)
        case originalStarted(String)
    }

    private struct State {
        var photos: [SourcePhoto] = []
        var photosError: PhotoSourceError?
        var images: [String: CGImage] = [:]
        var originals: [String: (data: Data, ext: String)] = [:]
        var thumbnailErrors: [String: PhotoSourceError] = [:]
        var originalErrors: [String: PhotoSourceError] = [:]
        var cloudFailures: [String: Int] = [:]
        var holdThumbnails = false
        var holdOriginals = false
        var waiters: [UUID: CheckedContinuation<Void, Error>] = [:]
        var thumbnailCalls: [String: Int] = [:]
        var originalCalls: [String: Int] = [:]
        var photosCalls = 0
        var queries: [SourceQuery] = []
        var inFlight = 0
        var maxInFlight = 0
    }

    private let lock = NSLock()
    private var state = State()
    let events: AsyncStream<Event>
    private let eventSink: AsyncStream<Event>.Continuation

    init(photos: [SourcePhoto] = []) {
        (events, eventSink) = AsyncStream<Event>.makeStream()
        state.photos = photos
    }

    private func locked<T>(_ body: (inout State) -> T) -> T {
        lock.lock()
        defer { lock.unlock() }
        return body(&state)
    }

    // MARK: Configuration

    func setPhotos(_ photos: [SourcePhoto]) { locked { $0.photos = photos } }
    func setPhotosError(_ error: PhotoSourceError?) { locked { $0.photosError = error } }
    func setImage(_ image: CGImage, for id: String) { locked { $0.images[id] = image } }
    func setOriginal(_ data: Data, ext: String, for id: String) { locked { $0.originals[id] = (data, ext) } }
    func failThumbnail(_ id: String, with error: PhotoSourceError) { locked { $0.thumbnailErrors[id] = error } }
    func failOriginal(_ id: String, with error: PhotoSourceError) { locked { $0.originalErrors[id] = error } }
    /// `original(for: id)` throws `.cloudUnavailable(id)` the next `times` calls, then succeeds.
    func cloudUnavailable(_ id: String, times: Int) { locked { $0.cloudFailures[id] = times } }
    func holdThumbnails(_ on: Bool = true) { locked { $0.holdThumbnails = on } }
    func holdOriginals(_ on: Bool = true) { locked { $0.holdOriginals = on } }

    /// Turns holding off and resumes every suspended call.
    func releaseAll() {
        let waiting = locked { s -> [CheckedContinuation<Void, Error>] in
            s.holdThumbnails = false
            s.holdOriginals = false
            let all = Array(s.waiters.values)
            s.waiters.removeAll()
            return all
        }
        waiting.forEach { $0.resume() }
    }

    // MARK: Observation

    func thumbnailCalls(_ id: String) -> Int { locked { $0.thumbnailCalls[id] ?? 0 } }
    func originalCalls(_ id: String) -> Int { locked { $0.originalCalls[id] ?? 0 } }
    var totalThumbnailCalls: Int { locked { $0.thumbnailCalls.values.reduce(0, +) } }
    var totalOriginalCalls: Int { locked { $0.originalCalls.values.reduce(0, +) } }
    var photosCalls: Int { locked { $0.photosCalls } }
    var queries: [SourceQuery] { locked { $0.queries } }
    /// Peak number of thumbnail/original calls in progress at the same time.
    var maxInFlight: Int { locked { $0.maxInFlight } }

    // MARK: PhotoSource

    func albums() async throws -> [SourceAlbum] { [] }

    func photos(matching query: SourceQuery) async throws -> [SourcePhoto] {
        try locked { s -> Result<[SourcePhoto], PhotoSourceError> in
            s.photosCalls += 1
            s.queries.append(query)
            if let error = s.photosError { return .failure(error) }
            return .success(s.photos)
        }.get()
    }

    func thumbnail(for identifier: String, maxPixel: Int) async throws -> CGImage {
        locked { $0.thumbnailCalls[identifier, default: 0] += 1 }
        eventSink.yield(.thumbnailStarted(identifier))
        try await begin(held: { $0.holdThumbnails })
        defer { end() }
        let (image, error) = locked { ($0.images[identifier], $0.thumbnailErrors[identifier]) }
        if let error { throw error }
        let served = image ?? ImageFixtures.checkerboard(size: 128, cell: 8)
        if max(served.width, served.height) > maxPixel {
            return ImageFixtures.checkerboard(size: maxPixel, cell: 8)
        }
        return served
    }

    func original(for identifier: String) async throws -> (data: Data, ext: String) {
        locked { $0.originalCalls[identifier, default: 0] += 1 }
        eventSink.yield(.originalStarted(identifier))
        try await begin(held: { $0.holdOriginals })
        defer { end() }
        let failure: PhotoSourceError? = locked { s in
            if let error = s.originalErrors[identifier] { return error }
            if let n = s.cloudFailures[identifier], n > 0 {
                s.cloudFailures[identifier] = n - 1
                return .cloudUnavailable(identifier)
            }
            return nil
        }
        if let failure { throw failure }
        if let stored = locked({ $0.originals[identifier] }) { return stored }
        return (Data("original:\(identifier)".utf8), "jpg")
    }

    // MARK: Holding and in-flight accounting

    private func begin(held: @escaping (State) -> Bool) async throws {
        locked { s in
            s.inFlight += 1
            s.maxInFlight = max(s.maxInFlight, s.inFlight)
        }
        // A few yields widen the window in which concurrent calls overlap.
        for _ in 0..<3 { await Task.yield() }
        let token = UUID()
        do {
            try await withTaskCancellationHandler {
                try await withCheckedThrowingContinuation { (c: CheckedContinuation<Void, Error>) in
                    let outcome: Int = locked { s in
                        if Task.isCancelled { return 2 }
                        if !held(s) { return 0 }
                        s.waiters[token] = c
                        return 1
                    }
                    if outcome == 0 { c.resume() }
                    if outcome == 2 { c.resume(throwing: CancellationError()) }
                }
            } onCancel: {
                let c = locked { $0.waiters.removeValue(forKey: token) }
                c?.resume(throwing: CancellationError())
            }
        } catch {
            end()
            throw error
        }
    }

    private func end() { locked { $0.inFlight -= 1 } }
}

extension SourcePhoto {
    /// Test helper: a photo captured `minutes` after 2026-07-01 00:00 UTC.
    static func fake(_ id: String, minutes: Int = 0, kind: PhotoKind = .photo,
                     width: Int = 4000, height: Int = 3000) -> SourcePhoto {
        SourcePhoto(identifier: id,
                    capturedAt: Date(timeIntervalSince1970: 1_782_864_000 + Double(minutes) * 60),
                    timeZoneSeconds: 7200, location: nil, pixelWidth: width, pixelHeight: height,
                    kind: kind, isCloudOnly: false)
    }
}
